// Extrai os dados essenciais da mensagem enviada pelo cliente via Evolution API
const payload = $input.first().json;
const data = payload.body?.data || payload.data || payload;

const rawJid = data.key?.remoteJid || data.remoteJid || '';
const telefone = rawJid.replace(/@.*$/, '').replace(/\D/g, '');
const pushName = data.pushName || data.key?.pushName || '';

// Extração do texto da mensagem (suporta texto puro, mensagem estendida e legenda de imagem/documento)
const messageObj = data.message || {};
const textoMensagem =
  messageObj.conversation ||
  messageObj.extendedTextMessage?.text ||
  messageObj.imageMessage?.caption ||
  messageObj.videoMessage?.caption ||
  messageObj.documentMessage?.caption ||
  '';

if (!telefone || telefone.length < 8 || !textoMensagem.trim()) {
  return []; // Ignora se não houver texto ou telefone válido
}

return [{
  json: {
    telefone,
    pushName,
    textoMensagem: textoMensagem.trim(),
    dataHora: new Date().toISOString()
  }
}];

