// Extrai e formata a resposta do ChatGPT para o formato exigido pelo CRM do Gabriel
const aiResponseRaw = $input.first().json;
const prevData = $('3. Extrair Dados da Mensagem').first().json;

let parsedAi = {};
try {
  const contentStr = aiResponseRaw.choices?.[0]?.message?.content || '{}';
  parsedAi = JSON.parse(contentStr);
} catch (e) {
  parsedAi = {};
}

const nomeFinal = (parsedAi.nome || prevData.pushName || '').trim();
const resumoFinal = (parsedAi.resumo_interacao || prevData.textoMensagem || 'Contato recebido pelo WhatsApp').trim();
const intencaoFinal = (parsedAi.intencao || 'Interesse em Mobiliário de Alto Padrão').trim();

// Payload exato para o Webhook do Gabriel (sem vendedor_id, fixado no back-end Vercel)
return [{
  json: {
    telefone: prevData.telefone,
    nome: nomeFinal,
    resumo_interacao: resumoFinal,
    intencao: intencaoFinal
  }
}];
